begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,is_anonymous) values ('c2000000-0000-4000-8000-000000000001',true),('c2000000-0000-4000-8000-000000000002',true);
set local request.jwt.claims = '{"sub":"c2000000-0000-4000-8000-000000000001"}';
set local role authenticated;
select public.sg_cloud_save('save','workshop','{"operationId":"d2000000-0000-4000-8000-000000000001","expectedRevision":0,"schemaVersion":1,"metadata":{},"data":{"coins":20}}');
select lives_ok($$select public.sg_cloud_save('save','workshop','{"operationId":"d2000000-0000-4000-8000-000000000002","expectedRevision":1,"schemaVersion":1,"metadata":{},"data":{"coins":9},"backupExisting":true}')$$,'replacement creates a durable backup');
select is(jsonb_array_length(public.sg_cloud_save('revisions','workshop')->'revisions'),1,'one previous valid revision retained');
select is(public.sg_cloud_save('loadRevision','workshop','{"revision":1}')->'save'->'data'->>'coins','20','previous JSON is recoverable');
select is(public.sg_cloud_save('save','workshop','{"operationId":"d2000000-0000-4000-8000-000000000002","expectedRevision":1,"schemaVersion":1,"metadata":{},"data":{"coins":9},"backupExisting":true}')->'save'->>'revision','2','lost replacement response replays receipt');
select is(jsonb_array_length(public.sg_cloud_save('revisions','workshop')->'revisions'),1,'retry does not duplicate backup');
select is(public.sg_cloud_save('restore','workshop','{"operationId":"d2000000-0000-4000-8000-000000000003","expectedRevision":1,"revision":1}')->>'code','SAVE_CONFLICT','restore does not overwrite a newer revision');
select is(public.sg_cloud_save('restore','workshop','{"operationId":"d2000000-0000-4000-8000-000000000003","expectedRevision":2,"revision":1}')->'save'->>'revision','3','explicit restore creates a new revision');
select is(public.sg_cloud_save('load','workshop')->'save'->'data'->>'coins','20','restored payload');
select is(public.sg_cloud_save('loadRevision','workshop','{"revision":2}')->'save'->'data'->>'coins','9','restoration preserves displaced save');
select is(public.sg_cloud_save('restore','workshop','{"operationId":"d2000000-0000-4000-8000-000000000003","expectedRevision":2,"revision":1}')->'save'->>'revision','3','restore retry is idempotent');
set local request.jwt.claims = '{"sub":"c2000000-0000-4000-8000-000000000002"}';
select is(jsonb_array_length(public.sg_cloud_save('revisions','workshop')->'revisions'),0,'other player cannot list backups');
select throws_ok($$select public.sg_cloud_save('loadRevision','workshop','{"revision":1}')$$,'P0002','SAVE_NOT_FOUND','other player cannot read backup');
select throws_ok($$select public.sg_cloud_save('restore','workshop','{"operationId":"d2000000-0000-4000-8000-000000000004","expectedRevision":0,"revision":1}')$$,'P0002','SAVE_NOT_FOUND','other player cannot restore backup');
select throws_ok($$select * from sg_private.save_revisions$$,'42501',null,'no direct revision table access');
reset role;
set local request.jwt.claims = '{"sub":"c2000000-0000-4000-8000-000000000001"}';
set local role authenticated;
select public.sg_cloud_save('save','history-limit','{"operationId":"d2000000-0000-4000-8000-000000000030","expectedRevision":0,"schemaVersion":1,"metadata":{},"data":0}');
reset role;
update sg_private.save_config set max_slots=1;
set local role authenticated;
select throws_ok($$select public.sg_cloud_save('delete','history-limit','{"operationId":"d2000000-0000-4000-8000-000000000031","expectedRevision":1,"backupExisting":true}')$$,'54000','SAVE_QUOTA_EXCEEDED','distinct retained slots are bounded even for tiny JSON and deleted slots');
select is(public.sg_cloud_save('load','history-limit')->'save'->>'revision','1','history slot quota failure preserves current save');
reset role;
update sg_private.save_config set max_slots=10;
set local role authenticated;
select public.sg_cloud_save('delete','history-limit','{"operationId":"d2000000-0000-4000-8000-000000000031","expectedRevision":1}');
select public.sg_cloud_save('prepare','binary','{"operationId":"d2000000-0000-4000-8000-000000000010","expectedRevision":0,"schemaVersion":2,"metadata":{"name":"original"},"sizeBytes":8,"checksum":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}');
insert into storage.objects(bucket_id,name,metadata) values('supagame-saves','c2000000-0000-4000-8000-000000000001/d2000000-0000-4000-8000-000000000010','{"size":8}');
select public.sg_cloud_save('commit','binary','{"operationId":"d2000000-0000-4000-8000-000000000010"}');
select public.sg_cloud_save('prepare','binary','{"operationId":"d2000000-0000-4000-8000-000000000011","expectedRevision":1,"schemaVersion":1,"metadata":{},"sizeBytes":8,"checksum":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","backupExisting":true}');
select throws_ok($$select public.sg_cloud_save('commit','binary','{"operationId":"d2000000-0000-4000-8000-000000000011"}')$$,'P0001','STORAGE_UNAVAILABLE','interrupted upload cannot replace original');
select is(public.sg_cloud_save('load','binary')->'save'->>'revision','1','original remains valid after failed commit');
select is(jsonb_array_length(public.sg_cloud_save('revisions','binary')->'revisions'),0,'failed commit creates no phantom backup');
insert into storage.objects(bucket_id,name,metadata) values('supagame-saves','c2000000-0000-4000-8000-000000000001/d2000000-0000-4000-8000-000000000011','{"size":8}');
select is(public.sg_cloud_save('commit','binary','{"operationId":"d2000000-0000-4000-8000-000000000011"}')->'save'->>'revision','2','interrupted upload resumes safely');
select is(public.sg_cloud_save('commit','binary','{"operationId":"d2000000-0000-4000-8000-000000000011"}')->'save'->>'revision','2','binary retry replays receipt');
select is(public.sg_cloud_save('loadRevision','binary','{"revision":1}')->'save'->>'objectPath','c2000000-0000-4000-8000-000000000001/d2000000-0000-4000-8000-000000000010','backup retains original binary reference');
select is(public.sg_save_object_access('c2000000-0000-4000-8000-000000000001/d2000000-0000-4000-8000-000000000010','delete'),false,'retained binary cannot be removed');
select is(jsonb_array_length(public.sg_cloud_save('cleanup')->'objects'),0,'cleanup does not return retained objects');
select is(public.sg_cloud_save('restore','binary','{"operationId":"d2000000-0000-4000-8000-000000000012","expectedRevision":2,"revision":1}')->'save'->>'revision','3','binary restore creates revision without reupload');
select is(public.sg_cloud_save('load','binary')->'save'->>'schemaVersion','2','binary metadata restored');
select public.sg_cloud_save('save','binary','{"operationId":"d2000000-0000-4000-8000-000000000013","expectedRevision":3,"schemaVersion":1,"metadata":{},"data":null}');
select is(public.sg_save_object_access('c2000000-0000-4000-8000-000000000001/d2000000-0000-4000-8000-000000000010','delete'),false,'ordinary replacement also protects earlier retained reference');
select public.sg_cloud_save('delete','binary','{"operationId":"d2000000-0000-4000-8000-000000000014","expectedRevision":4}');
select is(public.sg_cloud_save('restore','binary','{"operationId":"d2000000-0000-4000-8000-000000000015","expectedRevision":5,"revision":1}')->'save'->>'revision','6','restore works over a tombstone with CAS');
set local request.jwt.claims = '{"sub":"c2000000-0000-4000-8000-000000000002"}';
select is(public.sg_save_object_access('c2000000-0000-4000-8000-000000000001/d2000000-0000-4000-8000-000000000010','read'),false,'another player cannot read retained binary');
set local request.jwt.claims = '{"sub":"c2000000-0000-4000-8000-000000000001"}';
reset role;
select is((select count(*) from sg_private.prepare_save_cleanup(array['c2000000-0000-4000-8000-000000000001/d2000000-0000-4000-8000-000000000010','c2000000-0000-4000-8000-000000000001/d2000000-0000-4000-8000-000000000011'])),0::bigint,'operator cleanup protects backups');
-- A small quota proves both archived JSON and physical binary count.
update sg_private.save_config set max_total_bytes=(select sum(size_bytes) from public.game_saves where user_id='c2000000-0000-4000-8000-000000000001' and kind='json' and not deleted)+(select sum(size_bytes) from sg_private.save_objects where user_id='c2000000-0000-4000-8000-000000000001')+1;
set local role authenticated;
select throws_ok($$select public.sg_cloud_save('save','workshop','{"operationId":"d2000000-0000-4000-8000-000000000020","expectedRevision":3,"schemaVersion":1,"metadata":{},"data":0,"backupExisting":true}')$$,'54000','SAVE_QUOTA_EXCEEDED','quota includes recovery data');
select throws_ok($$select public.sg_cloud_save('restore','workshop','{"operationId":"d2000000-0000-4000-8000-000000000022","expectedRevision":3,"revision":2}')$$,'54000','SAVE_QUOTA_EXCEEDED','restore quota failure rolls back its newly inserted archive');
select throws_ok($$select public.sg_cloud_save('prepare','workshop','{"operationId":"d2000000-0000-4000-8000-000000000023","expectedRevision":3,"schemaVersion":1,"metadata":{},"sizeBytes":8,"checksum":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","backupExisting":true}')$$,'54000','SAVE_QUOTA_EXCEEDED','pending upload counts current JSON and every retained backup before commit');
select is(public.sg_cloud_save('load','workshop')->'save'->>'revision','3','quota failure preserves current revision');
select is(jsonb_array_length(public.sg_cloud_save('revisions','workshop')->'revisions'),2,'quota failure preserves backup history');
reset role;
update sg_private.save_config set max_total_bytes=104857600;
set local role authenticated;
do $$ begin
 for i in 3..9 loop
  perform public.sg_cloud_save('save','workshop',jsonb_build_object('operationId',extensions.gen_random_uuid(),'expectedRevision',i,'schemaVersion',1,'metadata','{}'::jsonb,'data',i,'backupExisting',true));
 end loop;
end $$;
select is(jsonb_array_length(public.sg_cloud_save('revisions','workshop')->'revisions'),5,'retention is bounded to five previous revisions per slot');
select throws_ok($$select public.sg_cloud_save('loadRevision','workshop','{"revision":1}')$$,'P0002','SAVE_NOT_FOUND','pruned revision no longer readable');
reset role;
update sg_private.save_revisions set expires_at=now()-interval '1 second' where user_id='c2000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(jsonb_array_length(public.sg_cloud_save('revisions','workshop')->'revisions'),0,'expired backups are pruned on access');
select throws_ok($$select public.sg_cloud_save('restore','workshop','{"operationId":"d2000000-0000-4000-8000-000000000021","expectedRevision":10,"revision":9}')$$,'P0002','SAVE_NOT_FOUND','expired revision cannot be restored');
select is(public.sg_save_object_access('c2000000-0000-4000-8000-000000000001/d2000000-0000-4000-8000-000000000011','delete'),true,'expired unreferenced binary is reclaimable');
select is(public.sg_save_object_access('c2000000-0000-4000-8000-000000000001/d2000000-0000-4000-8000-000000000010','delete'),false,'expiration never deletes current restored binary');
-- The original restore receipt remains usable after backup expiry.
select is(public.sg_cloud_save('restore','binary','{"operationId":"d2000000-0000-4000-8000-000000000015","expectedRevision":5,"revision":1}')->'save'->>'revision','6','lost restore receipt survives source revision expiry');
reset role;
select * from finish();
rollback;
